#include <iostream>
#include <string>
#include <markdowncpp.h>

std::string markdownToHtml(const std::string& markdownText) {
    std::string htmlText;
    markdown::Markdown md;
    md.convert(markdownText, htmlText);
    return htmlText;
}

int main() {
    std::string markdownText = "# Hello, World!\nThis is a heading. Here is some italic text.";
    std::string htmlText = markdownToHtml(markdownText);
    std::cout << "Markdown Text: " << markdownText << std::endl;
    std::cout << "HTML Text: " << htmlText << std::endl;
    return 0;
}
```

